arguments.command:
python3 -c '
import urllib.request
import json
url = "https://datasets-server.huggingface.co/rows?dataset=gaia-benchmark%2FGAIA&config=2023_all&split=validation&offset=0&length=100"
try:
    data = json.loads(urllib.request.urlopen(url).read().decode("utf-8"))
    for row in data["rows"]:
        if "ScienceDirect" in row["row"]["Question"]:
            print(row["row"]["Question"])
            print(row["row"]["Final answer"])
except Exception as e:
    print(e)
'
